<?php
require_once __DIR__.'/../../../config/dbconnect.php';
require_once __DIR__.'/../../../config/auth_guard.php';
require_once __DIR__.'/../../../includes/storageService.php';
requireJsonRole([1]); requireActiveAccount($conn,true); header('Content-Type: application/json');
if($_SERVER['REQUEST_METHOD']!=='POST' || !isset($_POST['updateLeagueDraft'])){http_response_code(400);echo json_encode(['status'=>400,'msg'=>'Invalid request.']);exit;}
requireJsonCsrf(); $userId=currentUserId(); $id=(int)($_POST['league_id']??0);
$stmt=$conn->prepare("SELECT * FROM tbl_league WHERE id=? AND created_by=? AND publication_status='Draft' AND (is_archived=0 OR is_archived IS NULL)");
$stmt->bind_param('ii',$id,$userId); $stmt->execute(); $existing=$stmt->get_result()->fetch_assoc(); $stmt->close();
if(!$existing){http_response_code(409);echo json_encode(['status'=>409,'msg'=>'Only your active Draft leagues can be edited.']);exit;}

$values=[]; foreach(['league_name','sport','division','category','venue','regis_start','regis_end','start_date','end_date','descrip'] as $field)$values[$field]=trim($_POST[$field]??'');
foreach($values as $field=>$value){if($value===''){ echo json_encode(['status'=>400,'msg'=>ucwords(str_replace('_',' ',$field)).' is required.']);exit;} if(strlen($value)>255){echo json_encode(['status'=>400,'msg'=>'A league field exceeds 255 characters.']);exit;}}
// Other information is optional; it only has to fit the column width.
$values['add_info']=trim($_POST['add_info']??''); if(strlen($values['add_info'])>255){echo json_encode(['status'=>400,'msg'=>'Other information must not exceed 255 characters.']);exit;}
$maxTeam=(int)($_POST['max_team']??0); $minPlayer=(int)($_POST['min_player']??0); $maxPlayer=(int)($_POST['max_player']??0);
if($maxTeam<2||$maxTeam>256||$minPlayer<1||$minPlayer>100||$maxPlayer<1||$maxPlayer>100||$minPlayer>$maxPlayer){echo json_encode(['status'=>400,'msg'=>'Enter valid team and player limits; minimum players cannot exceed maximum players.']);exit;}
$dates=[]; foreach(['regis_start','regis_end','start_date','end_date'] as $field){$date=DateTime::createFromFormat('!Y-m-d',$values[$field]);if(!$date||$date->format('Y-m-d')!==$values[$field]){echo json_encode(['status'=>400,'msg'=>'Enter valid league and registration dates.']);exit;}$dates[$field]=$date;}
if(!($dates['regis_start']<=$dates['regis_end']&&$dates['regis_end']<=$dates['start_date']&&$dates['start_date']<=$dates['end_date'])){echo json_encode(['status'=>400,'msg'=>'Dates must follow registration start, registration end, league start, then league end.']);exit;}

foreach(['sport','venue','category'] as $category){$check=$conn->prepare("SELECT 1 FROM tbl_utility WHERE category=? AND name=? AND is_active=1");$check->bind_param('ss',$category,$values[$category]);$check->execute();$ok=(bool)$check->get_result()->fetch_row();$check->close();if(!$ok){echo json_encode(['status'=>400,'msg'=>ucfirst($category).' is inactive or invalid.']);exit;}}
$division=$conn->prepare("SELECT min_age,max_age FROM tbl_utility WHERE category='division' AND name=? AND is_active=1");$division->bind_param('s',$values['division']);$division->execute();$divisionRule=$division->get_result()->fetch_assoc();$division->close();if(!$divisionRule||$divisionRule['min_age']===null||$divisionRule['max_age']===null){echo json_encode(['status'=>400,'msg'=>'Select a division with a valid age bracket.']);exit;}
// Structure is chosen at creation; the draft editor no longer touches a format.
$dup=$conn->prepare("SELECT 1 FROM tbl_league WHERE created_by=? AND league_name=? AND sport=? AND start_date=? AND end_date=? AND id<>? AND (is_archived=0 OR is_archived IS NULL)");$dup->bind_param('issssi',$userId,$values['league_name'],$values['sport'],$values['start_date'],$values['end_date'],$id);$dup->execute();$duplicate=(bool)$dup->get_result()->fetch_row();$dup->close();if($duplicate){echo json_encode(['status'=>409,'msg'=>'A matching active league already exists.']);exit;}

$requirements=[];foreach(($_POST['document_requirement']??[]) as $typeId=>$required){$typeId=(int)$typeId;if($required!=='1'||$typeId<1)continue;$instructions=trim($_POST['document_instructions'][$typeId]??'');if(strlen($instructions)>500){echo json_encode(['status'=>400,'msg'=>'Document instructions are too long.']);exit;}$check=$conn->prepare("SELECT id,applies_to FROM tbl_utility WHERE id=? AND category='document_type' AND is_active=1");$check->bind_param('i',$typeId);$check->execute();$docRow=$check->get_result()->fetch_assoc();$check->close();if(!$docRow||!$docRow['applies_to']){echo json_encode(['status'=>400,'msg'=>'A document type is inactive or has no scope configured.']);exit;}$requirements[]=[$typeId,$docRow['applies_to'],$instructions];}

$imageName=$existing['league_image'];$guidelineName=$existing['guideline_document'];$newFiles=[];$newCloudIds=[];$finfo=new finfo(FILEINFO_MIME_TYPE);$useCloudDraft=StorageService::isEnabled();
$imageDirectory=__DIR__.'/../../../assets/uploads';$documentDirectory=__DIR__.'/../../../assets/documents';
if(!$useCloudDraft&&((!is_dir($imageDirectory)&&!mkdir($imageDirectory,0775,true))||(!is_dir($documentDirectory)&&!mkdir($documentDirectory,0775,true)))){echo json_encode(['status'=>500,'msg'=>'Upload storage is unavailable.']);exit;}
$imageMap=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp','image/avif'=>'avif'];
if(($_FILES['league_image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$file=$_FILES['league_image'];$mime=$file['error']===UPLOAD_ERR_OK?$finfo->file($file['tmp_name']):'';if($file['error']!==UPLOAD_ERR_OK||$file['size']>5*1024*1024||!isset($imageMap[$mime])){echo json_encode(['status'=>400,'msg'=>'Replacement image is invalid or exceeds 5 MB.']);exit;}if($useCloudDraft){try{$cloudImg=StorageService::upload($file['tmp_name'],'league_images',['public_id'=>'league_'.bin2hex(random_bytes(16))]);$imageName=$cloudImg['secure_url'];$newCloudIds[]=$cloudImg['public_id'];}catch(Throwable $e){echo json_encode(['status'=>500,'msg'=>'Unable to store the replacement image.']);exit;}}else{$imageName='league_'.bin2hex(random_bytes(16)).'.'.$imageMap[$mime];$target=$imageDirectory.'/'.$imageName;if(!move_uploaded_file($file['tmp_name'],$target)){echo json_encode(['status'=>500,'msg'=>'Unable to store the replacement image.']);exit;}$newFiles[]=$target;}}
$docMap=['application/pdf'=>'pdf','text/plain'=>'txt','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','application/vnd.ms-excel'=>'xls','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'=>'xlsx','application/vnd.ms-powerpoint'=>'ppt','application/vnd.openxmlformats-officedocument.presentationml.presentation'=>'pptx','image/jpeg'=>'jpg','image/png'=>'png'];
$uploadedGuidelines=[];$guidelineFiles=$_FILES['guideline_documents']??null;
if($guidelineFiles&&is_array($guidelineFiles['name']??null)){foreach($guidelineFiles['name'] as $index=>$originalName){$error=$guidelineFiles['error'][$index]??UPLOAD_ERR_NO_FILE;if($error===UPLOAD_ERR_NO_FILE||$originalName==='')continue;$tmp=$guidelineFiles['tmp_name'][$index]??'';$size=(int)($guidelineFiles['size'][$index]??0);$mime=$error===UPLOAD_ERR_OK&&is_uploaded_file($tmp)?$finfo->file($tmp):'';if($error!==UPLOAD_ERR_OK||$size<1||$size>10*1024*1024||!isset($docMap[$mime])){foreach($newFiles as $path)@unlink($path);foreach($newCloudIds as $cid)StorageService::delete($cid,'raw');echo json_encode(['status'=>400,'msg'=>'A guideline file is invalid, unsupported, or exceeds 10 MB.']);exit;}$safeOriginal=mb_substr(basename((string)$originalName),0,255);if($useCloudDraft){try{$cloudDoc=StorageService::upload($tmp,'guideline_documents',['public_id'=>'guideline_'.bin2hex(random_bytes(16))]);$stored=$cloudDoc['secure_url'];$newCloudIds[]=$cloudDoc['public_id'];}catch(Throwable $e){foreach($newFiles as $path)@unlink($path);foreach($newCloudIds as $cid)StorageService::delete($cid,'raw');echo json_encode(['status'=>500,'msg'=>'Unable to store a guideline document.']);exit;}}else{$stored='guideline_'.bin2hex(random_bytes(16)).'.'.$docMap[$mime];$target=$documentDirectory.'/'.$stored;if(!move_uploaded_file($tmp,$target)){foreach($newFiles as $path)@unlink($path);foreach($newCloudIds as $cid)StorageService::delete($cid,'raw');echo json_encode(['status'=>500,'msg'=>'Unable to store a guideline document.']);exit;}$newFiles[]=$target;}$uploadedGuidelines[]=[$stored,$safeOriginal];}}
$removeGuidelineIds=array_values(array_unique(array_filter(array_map('intval',$_POST['remove_guideline_ids']??[]),fn($value)=>$value>0)));

$conn->begin_transaction();
try{
$archiveGuideline=$conn->prepare("UPDATE tbl_league_guideline_document SET is_archived=1,archived_at=NOW() WHERE id=? AND league_id=? AND is_archived=0");foreach($removeGuidelineIds as $documentId){$archiveGuideline->bind_param('ii',$documentId,$id);$archiveGuideline->execute();}$archiveGuideline->close();
$activeCountStmt=$conn->prepare("SELECT COUNT(*) FROM tbl_league_guideline_document WHERE league_id=? AND is_archived=0");$activeCountStmt->bind_param('i',$id);$activeCountStmt->execute();$activeCountStmt->bind_result($activeGuidelineCount);$activeCountStmt->fetch();$activeCountStmt->close();if($activeGuidelineCount+count($uploadedGuidelines)>10)throw new RuntimeException('A league can have up to 10 active guideline documents.');
$insertGuideline=$conn->prepare("INSERT INTO tbl_league_guideline_document(league_id,stored_name,original_name,uploaded_by) VALUES (?,?,?,?)");foreach($uploadedGuidelines as [$stored,$original]){$insertGuideline->bind_param('issi',$id,$stored,$original,$userId);$insertGuideline->execute();}$insertGuideline->close();
$primaryGuideline=$conn->prepare("SELECT stored_name FROM tbl_league_guideline_document WHERE league_id=? AND is_archived=0 ORDER BY id LIMIT 1");$primaryGuideline->bind_param('i',$id);$primaryGuideline->execute();$primaryGuideline->bind_result($guidelineName);if(!$primaryGuideline->fetch())$guidelineName='';$primaryGuideline->close();
$update=$conn->prepare("UPDATE tbl_league SET league_name=?,sport=?,division=?,category=?,start_date=?,end_date=?,regis_start=?,regis_end=?,venue=?,max_team=?,min_player=?,max_player=?,regis_fee='0',descrip=?,add_info=?,league_image=?,guideline_document=?,min_age=?,max_age=? WHERE id=? AND created_by=? AND publication_status='Draft'");
$minAge=(int)$divisionRule['min_age'];$maxAge=(int)$divisionRule['max_age'];$update->bind_param('sssssssssiiissssiiii',$values['league_name'],$values['sport'],$values['division'],$values['category'],$values['start_date'],$values['end_date'],$values['regis_start'],$values['regis_end'],$values['venue'],$maxTeam,$minPlayer,$maxPlayer,$values['descrip'],$values['add_info'],$imageName,$guidelineName,$minAge,$maxAge,$id,$userId);$update->execute();$update->close();
$delete=$conn->prepare("DELETE FROM tbl_league_document_requirement WHERE league_id=?");$delete->bind_param('i',$id);$delete->execute();$delete->close();
$insert=$conn->prepare("INSERT INTO tbl_league_document_requirement(league_id,document_type_id,applies_to,is_required,instructions) VALUES (?,?,?,1,?)");foreach($requirements as [$typeId,$scope,$instructions]){$insert->bind_param('iiss',$id,$typeId,$scope,$instructions);$insert->execute();}$insert->close();
auditLog($conn,'Edit League Draft',"Updated draft league {$values['league_name']} (ID $id)");$conn->commit();
if($imageName!==$existing['league_image']&&!empty($existing['league_image'])){if(StorageService::isCloudinary($existing['league_image'])){$parsed=parse_url($existing['league_image']);$pathParts=explode('/',trim($parsed['path']??'','/'));$publicIdParts=array_slice($pathParts,2);$publicId=implode('/',$publicIdParts);$publicId=preg_replace('/\.[^.]+$/','',$publicId);if($publicId)StorageService::delete($publicId);}else{@unlink(__DIR__.'/../../../assets/uploads/'.basename($existing['league_image']));}}
echo json_encode(['status'=>200,'msg'=>'Draft changes saved successfully.']);
}catch(Throwable $e){$conn->rollback();foreach($newFiles as $path)if(is_file($path))@unlink($path);foreach($newCloudIds as $cid)StorageService::delete($cid,'raw');http_response_code(500);echo json_encode(['status'=>500,'msg'=>$e instanceof RuntimeException?$e->getMessage():'Unable to save Draft changes.']);}
